 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY);prefs=getSharedPreferences("gesturelab",MODE_PRIVATE);load();sensors=(android.hardware.SensorManager)getSystemService(SENSOR_SERVICE);gyro=sensors.getDefaultSensor(android.hardware.Sensor.TYPE_GYROSCOPE);accel=sensors.getDefaultSensor(android.hardware.Sensor.TYPE_ACCELEROMETER);hid=new HidController(this,t->{if(usePhoneBridge)return;runOnUiThread(()->{status=t;if(t.startsWith("Connecting")||t.startsWith("Connected"))keepSetup();if(!linkConnected()&&armed)pause("Paused · connection lost");if(surface!=null)surface.invalidate();});});hid.remember(prefs.getString("host",null));bridge=new PhoneBridgeClient(this,new PhoneBridgeClient.Listener(){public void state(String t){if(!usePhoneBridge)return;status=t;if(t.startsWith("Connecting")||t.startsWith("Connected"))keepSetup();if(!bridge.connected&&armed)pause("Paused · phone link lost");if(surface!=null)surface.invalidate();}public void completed(String result){notice="DONE".equals(result)?"Done · "+bridge.profile:result.equals("CALIBRATE_COMMENTS")?"Set comments button in phone app":result.equals("OPEN_INSTAGRAM")?"Open Instagram first":result.equals("LOCKED")?"Unlock the phone first":result.equals("COOLDOWN")||result.equals("BUSY")?"Wait, then make a new gesture":"Action: "+result.toLowerCase();feedbackUntil=SystemClock.elapsedRealtime()+(result.equals("DONE")?900:4500);if(surface!=null)surface.invalidate();}public void contextChanged(String p){if(surface!=null){surface.sendAccessibilityEvent(android.view.accessibility.AccessibilityEvent.TYPE_WINDOW_CONTENT_CHANGED);surface.invalidate();}}});if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,()->onBackPressed());home();}
 private void load(){usePhoneBridge=prefs.getBoolean("phoneBridge",false);engine.mode=prefs.getInt("mode",0);engine.sensitivity=prefs.getFloat("gain",750);engine.scrollNotches=prefs.getInt("scrollNotches",1);engine.invert=prefs.getBoolean("invert",false);engine.rightWrist=prefs.getBoolean("right",false);engine.biasX=prefs.getFloat("bx",0);engine.biasY=prefs.getFloat("by",0);engine.biasZ=prefs.getFloat("bz",0);engine.neutralTilt=prefs.getFloat("tilt",0);engine.calibrated=prefs.getBoolean("calibrated",false);pulses.threshold=prefs.getFloat("pulse",300);fingers=prefs.getBoolean("fingers",false);}
 private void save(){prefs.edit().putBoolean("phoneBridge",usePhoneBridge).putInt("mode",engine.mode).putFloat("gain",(float)engine.sensitivity).putInt("scrollNotches",engine.scrollNotches).putBoolean("invert",engine.invert).putBoolean("right",engine.rightWrist).putFloat("bx",(float)engine.biasX).putFloat("by",(float)engine.biasY).putFloat("bz",(float)engine.biasZ).putFloat("tilt",(float)engine.neutralTilt).putBoolean("calibrated",engine.calibrated).putFloat("pulse",(float)pulses.threshold).putBoolean("fingers",fingers).apply();}
