 private boolean permission(){return checkSelfPermission(Manifest.permission.BLUETOOTH_CONNECT)==PackageManager.PERMISSION_GRANTED;}
 private void allow(){requestPermissions(new String[]{Manifest.permission.BLUETOOTH_CONNECT,Manifest.permission.BLUETOOTH_ADVERTISE},5);}
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(permission()){if(usePhoneBridge)bridge.connect(prefs.getString("host",null));else hid.open();}else status="Bluetooth access is off";home();}
 private void home(){options=false;surface=new Surface();setContentView(surface);}
 private void registerSensors(){sensors.unregisterListener(this);if(gyro!=null)sensors.registerListener(this,gyro,fingerTraining?10_000:20_000);if(accel!=null)sensors.registerListener(this,accel,fingers||fingerTraining?10_000:20_000);}
 private void arm(){if(!permission()){allow();return;}if(!linkConnected()){chooseComputer();return;}if(battery<10){notice="Charge to 10% before starting";return;}if(gyro==null||accel==null){notice="Required motion sensors unavailable";return;}armed=true;drag=false;testOnly=false;freezeUntil=SystemClock.elapsedRealtime()+900;handler.postDelayed(()->{if(armed)engine.neutral(tilt);},700);lastIntent=SystemClock.elapsedRealtime();engine.reset();air.reset();pulses.reset();notice="Air controls live · face down for 1 sec pauses";registerSensors();getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);WindowManager.LayoutParams a=getWindow().getAttributes();a.screenBrightness=.08f;getWindow().setAttributes(a);surface.invalidate();handler.postDelayed(()->{if(armed&&surface!=null)surface.performAccessibilityAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_ACCESSIBILITY_FOCUS,null);},350);}
 private void pause(String why){setupUntil=0;armed=calibrating=fingerTraining=false;drag=false;sensors.unregisterListener(this);if(hid!=null)hid.release();getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);WindowManager.LayoutParams a=getWindow().getAttributes();a.screenBrightness=WindowManager.LayoutParams.BRIGHTNESS_OVERRIDE_NONE;getWindow().setAttributes(a);notice=why;engine.reset();air.reset();pulses.reset();if(surface!=null)surface.invalidate();}
 private void keepSetup(){if(!resumed||armed)return;setupUntil=SystemClock.elapsedRealtime()+120_000;getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);WindowManager.LayoutParams a=getWindow().getAttributes();a.screenBrightness=.12f;getWindow().setAttributes(a);}
 private void chooseComputer(){pause("Select the computer you want to control");if(!permission()){allow();return;}keepSetup();List<BluetoothDevice> devices=hid.bonded();String[] names=new String[devices.size()+1];for(int i=0;i<devices.size();i++){String n=devices.get(i).getName();names[i]=n==null?"Paired device":n;}names[devices.size()]="Pair a new computer…";new AlertDialog.Builder(this).setTitle("Bluetooth computer").setItems(names,(d,which)->{if(which==devices.size()){if(checkSelfPermission(Manifest.permission.BLUETOOTH_ADVERTISE)!=PackageManager.PERMISSION_GRANTED){allow();return;}Intent i=new Intent(BluetoothAdapter.ACTION_REQUEST_DISCOVERABLE);i.putExtra(BluetoothAdapter.EXTRA_DISCOVERABLE_DURATION,120);startActivity(i);}else{prefs.edit().putString("host",devices.get(which).getAddress()).apply();if(usePhoneBridge)bridge.connect(devices.get(which).getAddress());else hid.connect(devices.get(which).getAddress());home();}}).show();}
 private void calibrate(){pause("Hold your wrist still in the pointing pose");if(gyro==null||accel==null){notice="Motion sensors unavailable";return;}calibrating=true;calibrateStart=SystemClock.elapsedRealtime()+1000;gsx=gsy=gsz=tiltSum=0;samples=0;badSamples=0;peak=0;registerSensors();home();getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}
