 private void onPulse(int count){notice="Detected "+count+" pulses";freezeUntil=SystemClock.elapsedRealtime()+300;lastIntent=SystemClock.elapsedRealtime();pulses.mute(SystemClock.elapsedRealtimeNanos()+450_000_000L);if(!testOnly){if(engine.mode==ControlEngine.POINTER)hid.click(count==2?1:2);else if(engine.mode==ControlEngine.SCROLL)page(count==2?1:-1);else page(count==2?1:-1);}vibrate();}
 private boolean linkConnected(){return usePhoneBridge?bridge.connected:hid.connected;}
 private void scrollStep(int amount){if(usePhoneBridge){if(!bridge.swipe(amount<0?1:-1))notice="Wait for the previous swipe, then gesture again";}else hid.mouse(0,0,0,amount);}
 private void page(int direction){if(usePhoneBridge)bridge.command(direction>0?"PRIMARY":"PREV");else if(engine.mode==ControlEngine.SCROLL&&hid.phone())hid.mouse(0,0,0,-direction*engine.scrollNotches);else hid.key(engine.mode==ControlEngine.SLIDES?(direction>0?79:80):(direction>0?78:75));freezeUntil=SystemClock.elapsedRealtime()+250;}
 private void vibrate(){pulses.mute(SystemClock.elapsedRealtimeNanos()+400_000_000L);Vibrator v=(Vibrator)getSystemService(VIBRATOR_SERVICE);if(v!=null&&v.hasVibrator())v.vibrate(VibrationEffect.createOneShot(25,VibrationEffect.DEFAULT_AMPLITUDE));}
 private void mode(){if(usePhoneBridge){menuResume=armed;pause("Choose phone control profile");profileMenu();return;}pause("Choose a control mode");new AlertDialog.Builder(this).setTitle("Control mode").setSingleChoiceItems(new String[]{"Pointer · wrist mouse","Scroll · one gesture, one step","Slides · wrist flicks"},engine.mode,(d,w)->{engine.mode=w;save();d.dismiss();home();}).show();}
