 @Override public void dump(String prefix,java.io.FileDescriptor fd,java.io.PrintWriter w,String[] args){super.dump(prefix,fd,w,args);w.println("GestureLabState resumed="+resumed+" armed="+armed+" calibrated="+engine.calibrated+" mode="+engine.mode+" step="+engine.scrollNotches+" phone="+hid.phone()+" bridge="+usePhoneBridge+" bridgePending="+bridge.pending+" bridgeResult="+bridge.lastResult+" profile="+bridge.profile+" connected="+linkConnected()+" gyroEvents="+gyroEvents+" reports="+hid.accepted+"/"+hid.attempted+" nativeClicks="+nativeClicks+" protocol="+hid.protocol+" error="+hid.lastError+" notice="+notice);}

 private void macMenu(){new AlertDialog.Builder(this).setTitle("MAC AIR SHORTCUTS").setItems(new String[]{"Pointer / scroll / slides","App and browser navigation","Presentations","Resume controls"},(d,w)->{if(w==0)new AlertDialog.Builder(this).setTitle("CONTROL MODE").setItems(new String[]{"Pointer","Scroll","Slides"},(dialog,index)->{engine.mode=index;save();finishMenu(null);}).show();else if(w==1)actionMenu("MAC NAVIGATION",new String[]{"Switch app","Next browser tab","Previous browser tab","Browser back","Browser forward","Mission Control","Previous desktop","Next desktop"},new String[]{"MAC_APP","MAC_TAB_NEXT","MAC_TAB_PREV","MAC_BACK","MAC_FORWARD","MAC_MISSION","MAC_DESKTOP_PREV","MAC_DESKTOP_NEXT"});else if(w==2)actionMenu("PRESENTATIONS",new String[]{"Next slide","Previous slide","Black screen toggle","Exit slideshow"},new String[]{"MAC_NEXT","MAC_PREV","MAC_BLACK","MAC_ESCAPE"});else finishMenu(null);}).setNegativeButton("Back to controls",(d,w)->finishMenu(null)).show();}
 private void macAction(String action){switch(action){case "MAC_APP":hid.keyCombo(8,43);break;case "MAC_TAB_NEXT":hid.keyCombo(1,43);break;case "MAC_TAB_PREV":hid.keyCombo(3,43);break;case "MAC_BACK":hid.keyCombo(8,47);break;case "MAC_FORWARD":hid.keyCombo(8,48);break;case "MAC_MISSION":hid.keyCombo(1,82);break;case "MAC_DESKTOP_PREV":hid.keyCombo(1,80);break;case "MAC_DESKTOP_NEXT":hid.keyCombo(1,79);break;case "MAC_NEXT":hid.key(79);break;case "MAC_PREV":hid.key(80);break;case "MAC_BLACK":hid.key(5);break;case "MAC_ESCAPE":hid.key(41);break;}}
