 private void actionMenu(String title,String[] labels,String[] actions){new AlertDialog.Builder(this).setTitle(title).setItems(labels,(d,w)->finishMenu(actions[w])).setNegativeButton("Back",(d,w)->airMenuRoot()).show();}
 private void finishMenu(String action){if(action!=null){if(action.startsWith("MAC_"))macAction(action);else if(usePhoneBridge)bridge.command(action);else notice="Phone controls are required";}home();if(menuResume&&linkConnected())arm();}
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private void addLabel(LinearLayout c,String text,int size){TextView t=new TextView(this);t.setText(text);t.setTextSize(size);t.setTextColor(Color.rgb(165,186,196));t.setGravity(Gravity.CENTER);t.setPadding(0,dp(8),0,dp(8));c.addView(t,new LinearLayout.LayoutParams(-1,-2));}
