  @Override public void onInitializeAccessibilityNodeInfo(android.view.accessibility.AccessibilityNodeInfo n){super.onInitializeAccessibilityNodeInfo(n);n.setClassName("android.widget.Button");n.setText(armed?(usePhoneBridge?"Phone "+bridge.profile+" primary action":engine.mode==0?"Click on computer":engine.mode==1?"Next reel / scroll step":"Next slide"):"Gesture Lab paused; tap Start on watch first");}
