  @Override protected void onDraw(Canvas c){super.onDraw(c);c.drawColor(Color.rgb(6,11,16));scale=getWidth()/480f;c.save();c.scale(scale,scale);text(c,"GESTURE LAB",240,65,20,Color.rgb(128,221,208));button(c,modeR,(usePhoneBridge?bridge.profile:modes[engine.mode])+"  ▾",false);
   String label=calibrating?(SystemClock.elapsedRealtime()<calibrateStart?"GET READY":"HOLD STILL"):fingerTraining?(trainingRest?"HOLD STILL":"PINCH "+peaks.size()+" / 5"):armed?(testOnly?"TEST ONLY":"PAUSE"):linkConnected()?"START":"CONNECT";
   button(c,mainR,label,armed||calibrating||fingerTraining);String s=status.length()>37?status.substring(0,34)+"…":status;text(c,s,240,285,15,Color.rgb(145,169,183));
   String h1=engine.mode==0?"Aim wrist → cursor":engine.mode==1?(usePhoneBridge?(bridge.profile.equals("MEDIA")?"Tilt → volume · pinch → play":bridge.profile.equals("COMMENTS")?"Tilt → scroll comments":bridge.profile.equals("NAV")?"Tilt → Back / Home":"Tilt → one scroll step"):"Tilt wrist → one scroll step"):"Flick wrist → change slide";
   String h2=usePhoneBridge?"Twist: action ↔ shortcuts":engine.mode==1?"Return to neutral → ready again":"Twist: mode ↔ shortcuts";
   text(c,h1,240,320,22,Color.rgb(214,232,239));text(c,h2,240,351,17,Color.rgb(143,177,192));
   button(c,new RectF(65,373,235,432),"CALIBRATE",false);button(c,new RectF(245,373,415,432),"OPTIONS",false);
   String diagnostic=armed?(engine.mode==1?(usePhoneBridge&&bridge.pending?"Swipe in progress":engine.scrollReady()?"Ready · one gesture = one step":"Return to neutral before next gesture"):engine.mode==0?"Pinch to click · face down pauses":"Flick once · return gently"):notice;if(SystemClock.elapsedRealtime()<feedbackUntil)diagnostic=notice;String n=diagnostic.length()>46?diagnostic.substring(0,43)+"…":diagnostic;text(c,n,240,455,12,Color.rgb(134,153,165));c.restore();}
  @Override public boolean onTouchEvent(MotionEvent e){float x=e.getX()/scale,y=e.getY()/scale;lastIntent=SystemClock.elapsedRealtime();if(e.getAction()==MotionEvent.ACTION_DOWN){downX=x;downY=y;downAt=SystemClock.elapsedRealtime();freezeUntil=Long.MAX_VALUE;pulses.mute(SystemClock.elapsedRealtimeNanos()+500_000_000L);return true;}if(e.getAction()==MotionEvent.ACTION_CANCEL){freezeUntil=SystemClock.elapsedRealtime()+300;return true;}if(e.getAction()==MotionEvent.ACTION_UP){freezeUntil=SystemClock.elapsedRealtime()+300;if(Math.abs(y-downY)>90){settings();return true;}if(modeR.contains(x,y))mode();else if(mainR.contains(x,y)){if(armed||calibrating||fingerTraining)pause("Paused");else arm();}else if(new RectF(245,373,415,432).contains(x,y))settings();else if(new RectF(65,373,235,432).contains(x,y))calibrate();invalidate();return true;}return true;}
